package cn.balltv.portal;
import org.junit.*;import static org.junit.Assert.*;
public class NeuralPolicyTest {
 @Test public void blurry1440And4kAreEligibleWithoutTreatingResolutionAsClarity(){assertTrue(NeuralPolicy.accepts(2560,1440,false));assertTrue(NeuralPolicy.accepts(3840,2160,false));assertFalse(NeuralPolicy.accepts(1280,720,true));assertFalse(NeuralPolicy.accepts(7680,4320,false));assertFalse(NeuralPolicy.accepts(0,720,false));}
 @Test public void processingBudgetUsesActualCadenceNotFixed28ms(){assertEquals(36,NeuralPolicy.budget(25,0),.001);assertEquals(30,NeuralPolicy.budget(30,0),.001);assertEquals(18,NeuralPolicy.budget(50,0),.001);assertEquals(15,NeuralPolicy.budget(60,0),.001);assertEquals(18,NeuralPolicy.budget(25,50),.001);}
 @Test public void inferenceBudgetCanFallWithoutChangingTheOriginalTextureSize(){int[][] levels=NeuralPolicy.levels(2560,1440);assertEquals(1920,levels[0][0]);assertEquals(1080,levels[0][1]);assertEquals(720,levels[NeuralPolicy.initial(levels)][1]);for(int i=1;i<levels.length;i++)assertTrue(levels[i][0]*levels[i][1]<levels[i-1][0]*levels[i-1][1]);}
 @Test public void portraitAndWideInputsKeepAspectAndBoundedWork(){for(int[] source:new int[][]{{2560,1080},{1080,1920},{640,480}})for(int[] level:NeuralPolicy.levels(source[0],source[1])){assertTrue(level[0]<=1920&&level[1]<=1080);assertEquals(source[0]/(double)source[1],level[0]/(double)level[1],.02);}}
 @Test public void first35msMeasurementsDoNotShutDown25fpsAi(){NeuralPolicy.Monitor m=new NeuralPolicy.Monitor();m.changed(0,false);for(int i=0;i<20;i++)assertEquals(0,m.sample(35.1,36,3000+i*600,true,false,false));}
 @Test public void oneSpikeAndStartupSamplesDoNotTriggerFallback(){NeuralPolicy.Monitor m=new NeuralPolicy.Monitor();m.changed(0,false);assertEquals(0,m.sample(120,30,100,true,false,false));for(int i=1;i<15;i++)assertTrue(m.sample(12,30,100+i*200,true,false,false)!=2);}
 @Test public void sustainedOverloadReducesWorkBeforeStopping(){NeuralPolicy.Monitor m=new NeuralPolicy.Monitor();m.changed(0,false);int action=0;for(int i=0;i<10&&action==0;i++)action=m.sample(40,30,3000+i*600,true,false,false);assertEquals(1,action);m.changed(9000,true);for(int i=0;i<8;i++)assertNotEquals(2,m.sample(20,30,12000+i*600,false,false,false));}
 @Test public void minimumWorkStopsOnlyAfterSustainedSevereOverload(){NeuralPolicy.Monitor m=new NeuralPolicy.Monitor();m.changed(0,true);for(int i=0;i<5;i++)assertEquals(0,m.sample(70,30,3000+i*600,false,false,false));int action=0;for(int i=5;i<16&&action==0;i++)action=m.sample(70,30,3000+i*600,false,false,false);assertEquals(2,action);}
 @Test public void pressureCanReduceWorkWithoutLosingAllEnhancement(){NeuralPolicy.Monitor m=new NeuralPolicy.Monitor();m.changed(0,false);int action=0;for(int i=0;i<10&&action==0;i++)action=m.sample(10,30,3000+i*600,true,false,true);assertEquals(1,action);}
}
